// Unicode folding for the search: canonical decomposition always, case
// folding unless the match is case sensitive (find spec: "case folding
// and normalisation of equivalent representations"). The tables live in
// unicode_fold_tables.h, generated by tools/unicode-tables.
#pragma once

#include <cstddef>
#include <cstdint>

namespace unicode {

// Writes the canonical decomposition (NFD, resolved to full depth) of
// one code point into `out` and returns how many code points it holds.
// A code point without a decomposition maps to itself (count 1).
std::size_t DecomposeInto(std::uint32_t code, std::uint32_t* out, std::size_t capacity);

// Writes the case folded form of one decomposed code point into `out`
// and returns how many code points it holds. Most folds map to one code
// point; the sharp s and the ligatures expand (two or three).
std::size_t FoldInto(std::uint32_t code, std::uint32_t* out, std::size_t capacity);

}  // namespace unicode
